async () => { const mg = window.MinigameFramework.currentMinigame; const C = mg.container; const sleep = ms => new Promise(r=>setTimeout(r,ms)); const start = C.querySelector('.tri-start'); if (start) start.click(); await sleep(120);
const plan = [['e9_push_own','push','approve',['none']],['e9_push_unstarted','push','deny_report',['unrequested_mfa_push']],['e9_fake_it_number','mail','report',['mfa_number_relay']],['e9_passphrase','choice','words'],['e9_signup_password','choice','unique'],['e9_security_answer','choice','madeup'],['e9_signin_ladder','choice','passkey'],['e9_shared_pc','choice','ask']];
for (const [id,kind,act,chips] of plan) { const row = C.querySelector('.mail-row[data-id="'+id+'"]'); if (!row) return { fail: 'row '+id }; row.click(); await sleep(70);
 if (kind === 'choice') { const o = C.querySelector('.tri-choice-option[data-action="'+act+'"]'); if (!o) return { fail: 'option '+id }; o.click(); await sleep(100); }
 else { const vb = kind === 'push' ? C.querySelector('.tri-verdict[data-action="'+act+'"]') : C.querySelector('.tri-verdict[data-verdict="'+act+'"]'); if (!vb) return { fail: 'verdict '+id }; vb.click(); await sleep(70); for (const ch of chips) { const inp = C.querySelector('input[data-chip="'+ch+'"]'); if (inp && !inp.checked) inp.click(); } const conf = C.querySelector('.tri-confirm'); if (!conf) return { fail: 'confirm '+id }; conf.click(); await sleep(100); }
 const nx = C.querySelector('.tri-next'); if (nx) { nx.click(); await sleep(100); } }
const s = mg.getTestState(); return s.triage.step === 'result'; }

async () => {
  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const q = s => { const m = window.MinigameFramework.currentMinigame; return m && m.container && m.container.querySelector(s); };
  const end = Date.now() + 60000;
  while (Date.now() < end) { const f = q('.tri-finish'); if (f && !f.disabled) { f.click(); return true; } await sleep(150); }
  return false;
}
